import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"🎮 늘보이드 서버 공식 위키","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),l={name:"index.md"};function i(n,t,s,c,d,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="🎮-늘보이드-서버-공식-위키" tabindex="-1">🎮 늘보이드 서버 공식 위키 <a class="header-anchor" href="#🎮-늘보이드-서버-공식-위키" aria-label="Permalink to &quot;🎮 늘보이드 서버 공식 위키&quot;">​</a></h1><h3 id="💡-늘보이드-서버란" tabindex="-1">💡 늘보이드 서버란? <a class="header-anchor" href="#💡-늘보이드-서버란" aria-label="Permalink to &quot;💡 늘보이드 서버란?&quot;">​</a></h3><blockquote><p><strong>&quot;API로 늘어나는 좀비를 모두 처치하고 탈출하세요!&quot;</strong></p></blockquote><p>입주 시 기본 좀비 킬 수는 <strong>N킬(회의 중)</strong> 로 시작되며, 시청자분들께서 <strong>API를 통해 킬 수를 추가</strong>하는 방식의 스트리머 서버입니다.</p><p>서버 기간 내에 추가된 좀비 수를 모두 처치하고 탈출하는 것을 목표로 하며, 탈출에 실패할 경우 받게 될 벌칙을 시청자분들과 함께 정해오시면 됩니다. *(벌칙 없이 가볍게 즐기러 오셔도 전혀 상관없습니다!)</p><p>처음 열어보는 서버에 처음 써보는 모드라 부족한 점이 많겠지만 열심히 운영하겠습니다. 가볍게 즐기는 마음으로 입주해 주세요!</p><h3 id="💡-tmi" tabindex="-1">💡 TMI <a class="header-anchor" href="#💡-tmi" aria-label="Permalink to &quot;💡 TMI&quot;">​</a></h3><ul><li>가끔 기습 섭주 이벤트가 발생합니다.<br> 섭주는 초반에 운영자로 활동하다가 서버와 스트리머 분들이 안정화되었을 때 플레이어로 활동합니다.</li></ul><hr><h3 id="도움-주신-분들" tabindex="-1">도움 주신 분들 <a class="header-anchor" href="#도움-주신-분들" aria-label="Permalink to &quot;도움 주신 분들&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>💻 <strong>개발</strong>: <code>&lt;Dr.부리부리&gt;</code> 님의 도움을 받아 열게 된 3D 모드 좀보이드 서버입니다.</li><li>⚖️ <strong>밸런스</strong>: 서버 밸런스 부분은 <code>&lt;듀파&gt;</code> 님의 도움을 받았습니다.</li><li>📚 <strong>위키 제작</strong>: 본 위키는 <code>&lt;잔디&gt;</code> 님의 도움을 받아 제작되었습니다.</li></ul></div>',11)])])}const _=a(l,[["render",i]]);export{p as __pageData,_ as default};
